\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{conjecture}[theorem]{Conjecture}

\newcommand{\T}{\mathbb{T}}
\newcommand{\R}{\mathbb{R}}
\newcommand{\ul}[1]{\underline{#1}}
\newcommand{\pinf}{+\infty}
\newcommand{\ninf}{-\infty}

\title{Transreal Arithmetic: The Exact Algebraic Cost of Total Division}
\author{Aristotle}
\date{2026-07-11}

\begin{document}

\begin{abstract}
We study the \emph{transreal numbers}, the extension $\T = \R \cup \{\pinf, \ninf, \Phi\}$ of the real line by two signed infinities and a distinguished element $\Phi$ (``nullity''), the canonical value of the indeterminate quotient $0/0$. The system is designed so that addition, multiplication, and division are all \emph{total}, with $\Phi$ serving as a global, self-propagating error element. We give a complete algebraic classification of the resulting structure. On the positive side we prove that $(\T, +, 0)$ and $(\T, \cdot, 1)$ are commutative monoids, that $\Phi$ is a two-sided absorbing element for both operations, that the finite reals embed conservatively, and that division is total with Anderson's identity $0/0 = \Phi$ holding exactly. On the negative side we prove that $\T$ is not a ring ($\pinf$ has no additive inverse, the annihilator law $0\cdot x = 0$ fails, distributivity fails, cancellation fails) and, more surprisingly, not a wheel either (the modified distributive law fails and the reciprocal is not an involution). We conclude that the transreals are precisely a pair of commutative monoids sharing a global absorbing element, equipped with a total but non-involutive division --- strictly weaker than both a ring and a wheel.
\end{abstract}

\maketitle

\section{Introduction}

The impossibility of division by zero is a structural fact about fields: adjoining a value for $1/0$ to any ring in which $1 \neq 0$ forces a contradiction. Yet the desire for \emph{total} arithmetic, where no operation ever raises an exception, recurs throughout computing and in projective geometry. Two strategies exist: the classical one-point projective line adjoins a single unsigned $\infty$ and yields a \emph{wheel}; Anderson's \emph{transreal arithmetic} adjoins two signed infinities together with nullity $\Phi = 0/0$, and is the closest algebraic model of IEEE~754 floating point with its $\pm\infty$ and \texttt{NaN}. We answer precisely which algebraic laws survive the transreal extension and which collapse.

\section{The transreal numbers}

\begin{definition}[Carrier]
The set of transreal numbers is $\T = \R \sqcup \{\pinf, \ninf, \Phi\}$, consisting of an embedded copy $\ul{r}$ of each real $r$, together with positive infinity $\pinf$, negative infinity $\ninf$, and nullity $\Phi$. We write $0 = \ul{0}$, $1 = \ul{1}$.
\end{definition}

\begin{definition}[Addition]
$\Phi + x = x + \Phi = \Phi$; $\ \pinf + \ninf = \ninf + \pinf = \Phi$; $\ \pinf + \pinf = \pinf$ and $\pinf + \ul{r} = \pinf$; $\ \ninf + \ninf = \ninf$ and $\ninf + \ul{r} = \ninf$; $\ \ul{a} + \ul{b} = \ul{a+b}$.
\end{definition}

\begin{definition}[Multiplication]
$\Phi \cdot x = x \cdot \Phi = \Phi$; $\ (\pinf)(\pinf) = (\ninf)(\ninf) = \pinf$, $(\pinf)(\ninf) = (\ninf)(\pinf) = \ninf$; for finite $b$, $(\pinf)\cdot\ul{b}$ is $\Phi$ if $b = 0$, $\pinf$ if $b > 0$, $\ninf$ if $b < 0$ (symmetrically, and with signs reversed against $\ninf$); $\ \ul{a}\cdot\ul{b} = \ul{ab}$. In particular $0 \cdot (\pm\infty) = \Phi$.
\end{definition}

\begin{definition}[Negation, reciprocal, division]
$-\Phi = \Phi$, $-(\pinf) = \ninf$, $-(\ninf) = \pinf$, $-\ul{a} = \ul{-a}$. The reciprocal is $1/\Phi = \Phi$, $1/(\pm\infty) = 0$, and $1/\ul{a} = \pinf$ if $a = 0$ else $\ul{a^{-1}}$. Division is $x/y = x \cdot (1/y)$, a total operation.
\end{definition}

\begin{lemma}[Six-way split]\label{lem:six}
Every $t \in \T$ satisfies exactly one of: $t = \Phi$; $t = \pinf$; $t = \ninf$; $t = \ul{r}$ with $r > 0$; $t = \ul{0}$; $t = \ul{r}$ with $r < 0$.
\end{lemma}
\begin{proof}
Immediate from the carrier definition and trichotomy of $\R$.
\end{proof}

\section{What survives}

\begin{theorem}[Global absorption]\label{thm:abs}
For all $x$, $\Phi + x = x + \Phi = \Phi$ and $\Phi \cdot x = x \cdot \Phi = \Phi$. Moreover $1/\Phi = \Phi$ and $\Phi/y = \Phi$ for all $y$.
\end{theorem}
\begin{proof}
Immediate from the defining clauses with $\Phi$ in the relevant position; $\Phi/y = \Phi\cdot(1/y) = \Phi$.
\end{proof}

\begin{theorem}[Conservative embedding]
The map $r \mapsto \ul{r}$ is injective and satisfies $\ul{a}+\ul{b} = \ul{a+b}$, $\ul{a}\cdot\ul{b} = \ul{ab}$, $-\ul{a} = \ul{-a}$. Every first-order identity of $\R$ not mentioning the singular values holds verbatim in $\T$.
\end{theorem}
\begin{proof}
These are the finite clauses of the definitions; injectivity is clear.
\end{proof}

\begin{theorem}[Additive commutative monoid]
$(\T, +, 0)$ is a commutative monoid: $x+y = y+x$, $(x+y)+z = x+(y+z)$, $0+x = x+0 = x$.
\end{theorem}
\begin{proof}[Proof sketch]
Commutativity and identity laws follow by case split (finite--finite reducing to real commutativity). For associativity, the only threatening interaction is $\pinf + \ninf = \Phi$; whenever such a cancellation occurs the result is $\Phi$, preserved across all groupings by Theorem~\ref{thm:abs}, so both groupings agree.
\end{proof}

\begin{theorem}[Multiplicative commutative monoid]
$(\T, \cdot, 1)$ is a commutative monoid: $xy = yx$, $(xy)z = x(yz)$, $1\cdot x = x\cdot 1 = x$.
\end{theorem}
\begin{proof}[Proof sketch]
Commutativity and identity laws follow by case split. For associativity, apply Lemma~\ref{lem:six} to each of $x,y,z$ ($6^3 = 216$ cases). Products with singular values obey closed forms (a positive real preserves an infinity's sign, a negative real flips it, a zero real yields $\Phi$); sign bookkeeping reduces to $\operatorname{sgn}(ab)=\operatorname{sgn}(a)\operatorname{sgn}(b)$, and any $0\cdot\infty = \Phi$ is preserved by absorption.
\end{proof}

\begin{theorem}[Totality and $0/0 = \Phi$]
Division is total. Moreover $1/0 = \pinf$, hence $0/0 = 0\cdot(\pinf) = \Phi$ and $1/0 = \ul{1}\cdot(\pinf) = \pinf$.
\end{theorem}
\begin{proof}
Both $\cdot$ and $1/(\cdot)$ are total. $1/0 = \pinf$ by definition; the two products follow from the zero and positive clauses of multiplication.
\end{proof}

\section{What collapses: the ring axioms}

\begin{theorem}[No additive inverse for $\pinf$]
There is no $y$ with $\pinf + y = 0$; hence $(\T,+)$ is not a group and $\T$ is not a ring.
\end{theorem}
\begin{proof}
$\pinf + y$ is $\pinf$ for $y$ finite or $\pinf$, and $\Phi$ for $y \in \{\ninf, \Phi\}$; never $\ul 0$.
\end{proof}

\begin{theorem}[Annihilator fails]
$0\cdot(\pinf) = \Phi \neq 0$.
\end{theorem}
\begin{proof}
Zero clause of multiplication; $\Phi \neq \ul 0$.
\end{proof}

\begin{theorem}[Distributivity fails]
With $x = \ul 2, y = \ul{-1}, z = \pinf$: $(x+y)z = \ul 1 \cdot \pinf = \pinf$, but $xz + yz = \pinf + \ninf = \Phi$.
\end{theorem}
\begin{proof}
Direct computation.
\end{proof}

\begin{theorem}[Cancellation fails]
$\pinf + \ul 1 = \pinf + \ul 2$ while $\ul 1 \neq \ul 2$.
\end{theorem}
\begin{proof}
Both sums equal $\pinf$; the embedding is injective.
\end{proof}

\section{What collapses: the wheel axioms}

A \emph{wheel} totalizes division via a reciprocal operator satisfying (W1) the involution law $1/(1/x) = x$ and (W2) the modified distributive law $(x+y)z + 0z = xz + yz$. The one-point projective completion of $\R$ is a wheel; the transreals are not.

\begin{theorem}[Wheel distributivity fails]
With $x = \ul 2, y = \ul 3, z = \pinf$: $(x+y)z + 0z = \ul 5\cdot\pinf + \Phi = \pinf + \Phi = \Phi$, whereas $xz + yz = \pinf + \pinf = \pinf$. Thus (W2) fails.
\end{theorem}
\begin{proof}
$0\cdot\pinf = \Phi$ poisons the left side by absorption; the right side is a genuine infinity.
\end{proof}

\begin{theorem}[Reciprocal is not an involution]
$1/(1/(\ninf)) = 1/0 = \pinf \neq \ninf$, so (W1) fails.
\end{theorem}
\begin{proof}
$1/(\ninf) = 0$ and $1/0 = \pinf \neq \ninf$.
\end{proof}

\begin{corollary}[Strict position]
$\T$ is neither a ring nor a wheel. Both wheel failures trace to the sign split of $\pm\infty$: the correction term $0z$ becomes $\Phi$ because two signed infinities force $0\cdot\infty$ indeterminate, and the reciprocal fails involution because $\pm\infty$ share the single reciprocal-of-zero image $\pinf$. A one-point completion has neither problem, and is a wheel.
\end{corollary}

\section{Classification theorem}

\begin{theorem}[Structure of the transreals]
$(\T, +, \cdot, -, 1/(\cdot), 0, 1)$ is a commutative monoid under $+$ (identity $0$) and under $\cdot$ (identity $1$), sharing a two-sided absorbing element $\Phi$, containing $\R$ conservatively, and equipped with a total division for which $1/0 = \pinf$ and $0/0 = \Phi$; but it is neither a ring nor a wheel. Equivalently, $\T$ is a pair of commutative monoids sharing a global absorbing element with a total but non-involutive division --- strictly weaker than both a ring and a wheel.
\end{theorem}

\section{Applications}

\textbf{IEEE 754.} The transreal design is the closest clean algebraic model of hardware floating point: $\pm\infty$ are signed overflow, $\Phi$ is \texttt{NaN}. Stickiness and $0/0$-production of \texttt{NaN} are exactly our absorption and totality theorems, and the negative results explain as theorems why floating point cannot be a ring. \textbf{Total semantics.} $\Phi$ is a canonical error value for exception-free total arithmetic. \textbf{Projective geometry.} The wheel comparison quantifies the algebraic difference between signed and unsigned completions of $\R$.

\section{Future directions}

\begin{conjecture}
Any structure containing $\R$ as a sub-semiring, making division total by adjoining finitely many infinite/undefined symbols, and retaining both left and right distributivity, must identify $1$ with $0$ and collapse to a point.
\end{conjecture}

\begin{conjecture}
The projective completion of $\R$ with $k$ distinguishable infinite elements is a wheel iff $k \le 1$; for $k \ge 2$ at least one wheel axiom fails. The transreal line is $k = 2$ (both fail); the one-point line is $k = 1$ (a wheel).
\end{conjecture}

\begin{conjecture}
A first-order theorem of real analysis extends verbatim to transreal-valued functions precisely when it never quantifies a limit, sum, or product across the singular set $\{\pinf, \ninf, \Phi\}$; statements that do fail, with the failure witnessed near $\Phi$.
\end{conjecture}

\begin{conjecture}
The transreal multiplicative monoid is, in a suitable sense, the free commutative monoid on the reals extended by signed infinities and a universal absorbing error element.
\end{conjecture}

\section{Conclusion}

Transreal arithmetic buys total division at an exactly measurable price: two commutative monoids sharing an absorbing $\Phi$ with $\R$ embedded conservatively survive, while the ring and wheel axioms collapse. The transreals occupy a precise slot --- strictly weaker than a ring, strictly weaker than a wheel --- and are the faithful algebraic shadow of floating-point arithmetic.

\end{document}

